        self.pageCount = res.last_page;\n                    self.page = res.current_page;\n                    self.loading = false;\n                })\n                .catch(error => {\n                    self.loading = false;\n                });\n        },\n        search() {\n            this.fetch(true);\n        },\n        download() {\n            let self = this;\n            self.loading = true;\n            const { itemsPerPage, sortBy, sortDesc } = self.options;\n            let data = {\n                goods_shipping_id: self.$props.goodsShipId,\n                per_page: itemsPerPage,\n                sort_by: sortBy,\n                sort_desc: sortDesc,\n                search: self.searchText,\n                extension: \"pdf\"\n            };\n            this.$store\n                .dispatch(\"goods/shipping/alteration/export\", data)\n                .then(response => {\n                    self.loading = false;\n                })\n                .catch(error => {\n                    self.loading = false;\n                });\n        },\n        reload() {\n            this.fetch();\n        }\n    }\n};\n</script>\n\n<style scoped>\n.v-select {\n    font-size: 1em;\n    font-weight: 100;\n}\n</style>\n"],"sourceRoot":""}]);
